/**
 * Harness case table — hand-authored CompiledPlans for every Tier 0 operation
 * the executor supports, plus combos. Each case doubles as a future planner
 * golden expectation (the JobGraph that should produce it gets written when
 * the planner lands).
 *
 * Fixtures are deterministic (generated by run.mjs), so geometry/durations
 * are constants here:
 *   a      320x180 30fps 8s testsrc2 + 440Hz sine, 48kHz stereo AAC, mp4
 *   b      480x270 25fps 5s testsrc2 + 880Hz sine, 44.1kHz MONO AAC, mp4
 *   music  10s 220Hz sine, 44.1kHz stereo PCM, wav
 *   logo   96x48 red@0.6 RGBA png
 */

import type { CompiledPlan, Geometry, Layer, Span } from '../src/schema';
import { SCHEMA_VERSION } from '../src/schema';

export const FIXTURES: Record<string, { file: string; kind: 'video' | 'audio' | 'image' | 'timed-text' }> = {
  a: { file: 'fA.mp4', kind: 'video' },
  b: { file: 'fB.mp4', kind: 'video' },
  music: { file: 'music.wav', kind: 'audio' },
  logo: { file: 'logo.png', kind: 'image' },
  subs: { file: 'subs.vtt', kind: 'timed-text' },
  // tier-1 fixtures (docs-check.mjs generates/copies these)
  speech: { file: 'speech.mp4', kind: 'video' },     // flite TTS + testsrc2
  noisy: { file: 'noisy.wav', kind: 'audio' },       // 0 dB speech+noise mix
  portrait: { file: 'portrait.jpg', kind: 'image' }, // web-bg-removal's demo photo (fetched by docs-check)
};

const A: Geometry = { w: 320, h: 180 };
const B: Geometry = { w: 480, h: 270 };
const DUR_A = 8;
const DUR_B = 5;
const AUDIO = { rate: 48000, channels: 2 };

/** Full-frame layer scaled to fill the canvas. */
const fill = (src: Geometry, canvas: Geometry, input = 0, opacity = 1): Layer => ({
  input,
  srcRect: { x: 0, y: 0, w: src.w, h: src.h },
  transform: [canvas.w / src.w, 0, 0, 0, canvas.h / src.h, 0],
  opacity,
  blend: 'over',
});

const bind = (asset: string, slot: number, s: number, e: number, off: number, track: 'video' | 'audio' = 'video') =>
  ({ slot, asset, track, sourceStart: s, sourceEnd: e, offset: off });

/** Single-span A/V plan over asset 'a' with a given composite. */
function singleAV(canvas: Geometry, layers: Layer[], overrides: Partial<CompiledPlan['output']> = {}, dur = DUR_A): CompiledPlan {
  return {
    schemaVersion: SCHEMA_VERSION,
    canvas,
    audioFormat: AUDIO,
    output: { container: 'mp4', video: { from: { node: 'x' }, quality: 'medium' }, audio: { from: { asset: 'a', track: 'audio' } }, ...overrides },
    strategy: { video: 'reencode', audio: 'reencode' },
    spans: [{
      start: 0, end: dur,
      video: { bindings: [bind('a', 0, 0, dur, 0)], composite: { canvas, layers } },
      audio: { bindings: [bind('a', 0, 0, dur, 0, 'audio')], mode: 'single' },
    }],
  };
}

export interface Expected {
  hasVideo: boolean;
  hasAudio: boolean;
  w?: number;
  h?: number;
  dur: number;
  durTol?: number;
  /** substring of ffprobe format_name */
  format?: string;
  maxBytes?: number;
  /** ffmpeg filter/ref args (input(s) prepended by the driver); output compared by SSIM */
  ssimRef?: { inputs: string[]; args: string[] };
  ssimMin?: number;
  /** [from, to, min mean dB] regions that must be non-silent */
  audioNonSilentAt?: [number, number, number][];
  /** this case's mean volume must exceed the named case's by >= deltaDb */
  louderThanCase?: { name: string; deltaDb: number };
}

export interface Case {
  name: string;
  plan: CompiledPlan;
  expected: Expected;
}

const av = { hasVideo: true, hasAudio: true };

export const CASES: Case[] = [
  {
    name: 'transcode',
    plan: singleAV(A, [fill(A, A)]),
    expected: { ...av, w: 320, h: 180, dur: DUR_A, audioNonSilentAt: [[1, 3, -40]] },
  },
  {
    name: 'convert-mkv',
    plan: singleAV(A, [fill(A, A)], { container: 'mkv' }),
    expected: { ...av, w: 320, h: 180, dur: DUR_A, format: 'matroska' },
  },
  {
    name: 'convert-webm',
    plan: singleAV(A, [fill(A, A)], { container: 'webm' }),
    expected: { ...av, w: 320, h: 180, dur: DUR_A, format: 'webm' },
  },
  {
    name: 'compress',
    plan: singleAV(A, [fill(A, A)], {
      video: { from: { node: 'x' }, quality: 'low' },
      audio: { from: { asset: 'a', track: 'audio' }, bitrate: 64000 },
    }),
    expected: { ...av, w: 320, h: 180, dur: DUR_A, maxBytes: 1_500_000 },
  },
  {
    name: 'resize-half',
    plan: singleAV({ w: 160, h: 90 }, [fill(A, { w: 160, h: 90 })]),
    expected: {
      ...av, w: 160, h: 90, dur: DUR_A,
      ssimRef: { inputs: ['fA.mp4'], args: ['-vf', 'scale=160:90'] }, ssimMin: 0.85,
    },
  },
  {
    name: 'crop-left',
    plan: singleAV({ w: 160, h: 180 }, [{
      input: 0, srcRect: { x: 0, y: 0, w: 160, h: 180 }, transform: [1, 0, 0, 0, 1, 0], opacity: 1, blend: 'over',
    }]),
    expected: {
      ...av, w: 160, h: 180, dur: DUR_A,
      ssimRef: { inputs: ['fA.mp4'], args: ['-vf', 'crop=160:180:0:0'] }, ssimMin: 0.85,
    },
  },
  {
    name: 'flip-h',
    plan: singleAV(A, [{
      input: 0, srcRect: { x: 0, y: 0, w: 320, h: 180 }, transform: [-1, 0, 320, 0, 1, 0], opacity: 1, blend: 'over',
    }]),
    expected: {
      ...av, w: 320, h: 180, dur: DUR_A,
      ssimRef: { inputs: ['fA.mp4'], args: ['-vf', 'hflip'] }, ssimMin: 0.85,
    },
  },
  {
    name: 'rotate-90',
    plan: singleAV({ w: 180, h: 320 }, [{
      input: 0, srcRect: { x: 0, y: 0, w: 320, h: 180 }, transform: [0, -1, 180, 1, 0, 0], opacity: 1, blend: 'over',
    }]),
    expected: {
      ...av, w: 180, h: 320, dur: DUR_A,
      ssimRef: { inputs: ['fA.mp4'], args: ['-vf', 'transpose=1'] }, ssimMin: 0.85,
    },
  },
  {
    name: 'trim',
    plan: {
      schemaVersion: SCHEMA_VERSION,
      canvas: A,
      audioFormat: AUDIO,
      output: { container: 'mp4', video: { from: { node: 'x' } }, audio: { from: { asset: 'a', track: 'audio' } } },
      strategy: { video: 'reencode', audio: 'reencode' },
      spans: [{
        start: 0, end: 3,
        video: { bindings: [bind('a', 0, 2, 5, -2)], composite: { canvas: A, layers: [fill(A, A)] } },
        audio: { bindings: [bind('a', 0, 2, 5, -2, 'audio')], mode: 'single' },
      }],
    },
    expected: { ...av, w: 320, h: 180, dur: 3 },
  },
  {
    name: 'concat',
    plan: {
      schemaVersion: SCHEMA_VERSION,
      canvas: B,
      audioFormat: AUDIO,
      output: { container: 'mp4', video: { from: { node: 'x' } }, audio: { from: { node: 'x' } } },
      strategy: { video: 'reencode', audio: 'reencode' },
      spans: [
        {
          start: 0, end: DUR_A,
          video: { bindings: [bind('a', 0, 0, DUR_A, 0)], composite: { canvas: B, layers: [fill(A, B)] } },
          audio: { bindings: [bind('a', 0, 0, DUR_A, 0, 'audio')], mode: 'single' },
        },
        {
          start: DUR_A, end: DUR_A + DUR_B,
          video: { bindings: [bind('b', 0, 0, DUR_B, DUR_A)], composite: { canvas: B, layers: [fill(B, B)] } },
          audio: { bindings: [bind('b', 0, 0, DUR_B, DUR_A, 'audio')], mode: 'single' },
        },
      ],
    },
    expected: { ...av, w: 480, h: 270, dur: DUR_A + DUR_B, audioNonSilentAt: [[1, 3, -40], [9, 12, -40]] },
  },
  {
    name: 'loop',
    plan: {
      schemaVersion: SCHEMA_VERSION,
      canvas: A,
      audioFormat: AUDIO,
      output: { container: 'mp4', video: { from: { node: 'x' } }, audio: { from: { node: 'x' } } },
      strategy: { video: 'reencode', audio: 'reencode' },
      spans: [0, 1].map((i): Span => ({
        start: i * DUR_A, end: (i + 1) * DUR_A,
        video: { bindings: [bind('a', 0, 0, DUR_A, i * DUR_A)], composite: { canvas: A, layers: [fill(A, A)] } },
        audio: { bindings: [bind('a', 0, 0, DUR_A, i * DUR_A, 'audio')], mode: 'single' },
      })),
    },
    expected: { ...av, w: 320, h: 180, dur: 2 * DUR_A },
  },
  {
    name: 'watermark',
    plan: {
      schemaVersion: SCHEMA_VERSION,
      canvas: A,
      audioFormat: AUDIO,
      output: { container: 'mp4', video: { from: { node: 'x' } }, audio: { from: { asset: 'a', track: 'audio' } } },
      strategy: { video: 'reencode', audio: 'reencode' },
      spans: [{
        start: 0, end: DUR_A,
        video: {
          bindings: [bind('a', 0, 0, DUR_A, 0)],
          staticSlots: { 1: 'logo' },
          composite: {
            canvas: A,
            layers: [
              fill(A, A),
              // logo 96x48 scaled to 80x40, bottom-right with 8px margin
              { input: 1, srcRect: { x: 0, y: 0, w: 96, h: 48 }, transform: [80 / 96, 0, 232, 0, 40 / 48, 132], opacity: 1, blend: 'over' },
            ],
          },
        },
        audio: { bindings: [bind('a', 0, 0, DUR_A, 0, 'audio')], mode: 'single' },
      }],
    },
    expected: {
      ...av, w: 320, h: 180, dur: DUR_A,
      ssimRef: {
        inputs: ['fA.mp4', 'logo.png'],
        args: ['-filter_complex', '[1:v]scale=80:40[l];[0:v][l]overlay=232:132'],
      },
      ssimMin: 0.85,
    },
  },
  {
    name: 'hstack-self',
    // left half ‖ right half of the SAME asset — two slots, one source
    plan: {
      schemaVersion: SCHEMA_VERSION,
      canvas: A,
      audioFormat: AUDIO,
      output: { container: 'mp4', video: { from: { node: 'x' } }, audio: { from: { asset: 'a', track: 'audio' } } },
      strategy: { video: 'reencode', audio: 'reencode' },
      spans: [{
        start: 0, end: DUR_A,
        video: {
          bindings: [bind('a', 0, 0, DUR_A, 0), bind('a', 1, 0, DUR_A, 0)],
          composite: {
            canvas: A,
            layers: [
              { input: 0, srcRect: { x: 0, y: 0, w: 160, h: 180 }, transform: [1, 0, 0, 0, 1, 0], opacity: 1, blend: 'over' },
              { input: 1, srcRect: { x: 160, y: 0, w: 160, h: 180 }, transform: [1, 0, 160, 0, 1, 0], opacity: 1, blend: 'over' },
            ],
          },
        },
        audio: { bindings: [bind('a', 0, 0, DUR_A, 0, 'audio')], mode: 'single' },
      }],
    },
    expected: { ...av, w: 320, h: 180, dur: DUR_A },
  },
  {
    name: 'crossfade',
    plan: {
      schemaVersion: SCHEMA_VERSION,
      canvas: B,
      audioFormat: AUDIO,
      output: { container: 'mp4', video: { from: { node: 'x' } }, audio: { from: { node: 'x' } } },
      strategy: { video: 'reencode', audio: 'reencode' },
      spans: [
        {
          start: 0, end: 7,
          video: { bindings: [bind('a', 0, 0, 7, 0)], composite: { canvas: B, layers: [fill(A, B)] } },
          audio: { bindings: [bind('a', 0, 0, 7, 0, 'audio')], mode: 'single' },
        },
        {
          start: 7, end: 8,
          video: {
            bindings: [bind('a', 0, 7, 8, 0), bind('b', 1, 0, 1, 7)],
            composite: { canvas: B, layers: [fill(A, B, 0), fill(B, B, 1, 0)] },
            opacityRamps: { 1: { from: 0, to: 1, over: [7, 8] } },
          },
          audio: {
            bindings: [bind('a', 0, 7, 8, 0, 'audio'), bind('b', 1, 0, 1, 7, 'audio')],
            mode: 'mix',
            gainRamps: { 0: { from: 1, to: 0, over: [7, 8] }, 1: { from: 0, to: 1, over: [7, 8] } },
          },
        },
        {
          start: 8, end: 12,
          video: { bindings: [bind('b', 0, 1, DUR_B, 7)], composite: { canvas: B, layers: [fill(B, B)] } },
          audio: { bindings: [bind('b', 0, 1, DUR_B, 7, 'audio')], mode: 'single' },
        },
      ],
    },
    expected: {
      ...av, w: 480, h: 270, dur: 12,
      audioNonSilentAt: [[1, 3, -40], [7.2, 7.8, -40], [9, 11, -40]],
    },
  },
  {
    name: 'extract-audio',
    plan: {
      schemaVersion: SCHEMA_VERSION,
      canvas: { w: 2, h: 2 }, // unused; no video lane
      audioFormat: AUDIO,
      output: { container: 'wav', audio: { from: { asset: 'a', track: 'audio' } } },
      strategy: { video: 'reencode', audio: 'reencode' },
      spans: [{
        start: 0, end: DUR_A,
        audio: { bindings: [bind('a', 0, 0, DUR_A, 0, 'audio')], mode: 'single' },
      }],
    },
    expected: { hasVideo: false, hasAudio: true, dur: DUR_A, audioNonSilentAt: [[1, 6, -40]] },
  },
  {
    name: 'mute',
    plan: {
      schemaVersion: SCHEMA_VERSION,
      canvas: A,
      output: { container: 'mp4', video: { from: { node: 'x' } } },
      strategy: { video: 'reencode', audio: 'none' },
      spans: [{
        start: 0, end: DUR_A,
        video: { bindings: [bind('a', 0, 0, DUR_A, 0)], composite: { canvas: A, layers: [fill(A, A)] } },
      }],
    },
    expected: { hasVideo: true, hasAudio: false, w: 320, h: 180, dur: DUR_A },
  },
  {
    name: 'volume-2x',
    plan: {
      ...singleAV(A, [fill(A, A)]),
      spans: [{
        start: 0, end: DUR_A,
        video: { bindings: [bind('a', 0, 0, DUR_A, 0)], composite: { canvas: A, layers: [fill(A, A)] } },
        audio: {
          bindings: [bind('a', 0, 0, DUR_A, 0, 'audio')],
          mode: 'single',
          gainRamps: { 0: { from: 2, to: 2, over: [0, DUR_A] } },
        },
      }],
    },
    expected: { ...av, w: 320, h: 180, dur: DUR_A, louderThanCase: { name: 'transcode', deltaDb: 3 } },
  },
  {
    name: 'swap-audio',
    plan: {
      schemaVersion: SCHEMA_VERSION,
      canvas: A,
      audioFormat: AUDIO,
      output: { container: 'mp4', video: { from: { node: 'x' } }, audio: { from: { asset: 'music', track: 'audio' } } },
      strategy: { video: 'reencode', audio: 'reencode' },
      spans: [{
        start: 0, end: DUR_A,
        video: { bindings: [bind('a', 0, 0, DUR_A, 0)], composite: { canvas: A, layers: [fill(A, A)] } },
        audio: { bindings: [bind('music', 0, 0, DUR_A, 0, 'audio')], mode: 'single' },
      }],
    },
    expected: { ...av, w: 320, h: 180, dur: DUR_A, audioNonSilentAt: [[1, 6, -40]] },
  },
  {
    name: 'combo-fused',
    // crop left half + resize to 80x90 + flip-h, fused into ONE layer
    plan: singleAV({ w: 80, h: 90 }, [{
      input: 0,
      srcRect: { x: 0, y: 0, w: 160, h: 180 },
      // scale (0.5, 0.5) then flip about the 80px canvas: [-0.5, 0, 80, 0, 0.5, 0]
      transform: [-0.5, 0, 80, 0, 0.5, 0],
      opacity: 1,
      blend: 'over',
    }]),
    expected: {
      ...av, w: 80, h: 90, dur: DUR_A,
      ssimRef: { inputs: ['fA.mp4'], args: ['-vf', 'crop=160:180:0:0,scale=80:90,hflip'] }, ssimMin: 0.8,
    },
  },
  {
    name: 'combo-trim-mkv',
    plan: {
      schemaVersion: SCHEMA_VERSION,
      canvas: A,
      audioFormat: AUDIO,
      output: { container: 'mkv', video: { from: { node: 'x' } }, audio: { from: { asset: 'a', track: 'audio' } } },
      strategy: { video: 'reencode', audio: 'reencode' },
      spans: [{
        start: 0, end: 4,
        video: { bindings: [bind('a', 0, 2, 6, -2)], composite: { canvas: A, layers: [fill(A, A)] } },
        audio: { bindings: [bind('a', 0, 2, 6, -2, 'audio')], mode: 'single' },
      }],
    },
    expected: { ...av, w: 320, h: 180, dur: 4, format: 'matroska' },
  },
];
